export interface SupplierReturnOut {
  return_id: number;
  /** SRN-YYYY-NNNNN, on the return note */
  return_number: string;
  vendor_id: number;
  vendor_name: string;
  batch_id: number;
  batch_no: string;
  expiry_date: string;
  drug_id: number;
  drug_name: string;
  drug_code: string;
  qty: number;
  unit_cost: number;
  /** What left the pharmacy's inventory into the claim on the supplier */
  value_at_cost: number;
  reason: "Expired" | "NearExpiry" | "Recall" | "Damaged" | "Excess" | "WrongSupply" | "Other";
  recall_id: number | null;
  recall_number: string | null;
  note: string;
  /** Returned (awaiting the credit note), Credited (confirmed: its credit pays the supplier's bills) or Refused (written off) */
  status: "Returned" | "Credited" | "Refused";
  returned_by_name: string;
  returned_at: string;
  credit_note_no: string | null;
  credit_note_date: string | null;
  credit_amount: number | null;
  /** Already used to pay this supplier's bills */
  credit_applied: number;
  /** Credited only: what is left to pay a bill with (method SupplierCredit) */
  credit_left: number | null;
  decided_by_name: string | null;
  decided_at: string | null;
  decision_note: string | null;
}

/** The supplier's credit note for a return, confirmed by the accountant. */
export interface SupplierCreditIn {
  credit_note_no: string;
  credit_note_date: string;
  /** What the supplier credits; below the value at cost the difference is a write-off, above it a gain on the write-off account */
  credit_amount: number | string;
  note?: string | null;
}

export interface SupplierRefusalIn {
  /** Why the supplier gives nothing: the claim is written off */
  note: string;
}

/** Chart of accounts — GET /api/v1/finance/gl/accounts (who may call: holders of finance.gl.view). */
export function glAccounts(): Promise<GlAccountOut[]> {
  return api<GlAccountOut[]>("GET", `/finance/gl/accounts`, undefined);
}

/** General ledger entries — GET /api/v1/finance/gl/ledger (who may call: holders of finance.gl.view). */
export function glLedger(query?: { account_code?: string | null; date_from?: string | null; date_to?: string | null; limit?: number }): Promise<LedgerEntryOut[]> {
  return api<LedgerEntryOut[]>("GET", withQuery(`/finance/gl/ledger`, query), undefined);
}

/** Add a vendor / contractor — POST /api/v1/finance/vendors (who may call: holders of finance.vendor.manage). */
export function addVendor(body: VendorIn): Promise<VendorOut> {
  return api<VendorOut>("POST", `/finance/vendors`, body, { idempotent: true });
}

/** Shifts (Cash Drop Verification workspace) — GET /api/v1/finance/cash-shifts (who may call: holders of finance.shift.view_all). */
export function listShifts(query?: { status?: "Open" | "PendingCollection" | "Verified" | null; limit?: number }): Promise<CashShiftListItemOut[]> {
  return api<CashShiftListItemOut[]>("GET", withQuery(`/finance/cash-shifts`, query), undefined);
}

/** Shift summary (expected cash by transaction type) — GET /api/v1/finance/cash-shifts/{shift_id} (who may call: holders of finance.shift.operate or finance.shift.view_all). */
export function getShift(shift_id: number): Promise<CashShiftSummaryOut> {
  return api<CashShiftSummaryOut>("GET", `/finance/cash-shifts/${shift_id}`, undefined);
}

/** Accountant: Approve Cash Drop (dual control for large amounts) — POST /api/v1/finance/cash-shifts/{shift_id}/cash-drop (who may call: holders of finance.cash_drop.verify). */
export function cashDrop(shift_id: number, body: CashDropIn): Promise<CashShiftSummaryOut> {
  return api<CashShiftSummaryOut>("POST", `/finance/cash-shifts/${shift_id}/cash-drop`, body, { idempotent: true });
}

/** Approval queue visible to me (or my own requests with mine=true) — GET /api/v1/approvals (who may call: any logged-in user: the pending requests whose required_permission they hold, or their own with mine=true). */
export function listApprovals(query?: { status?: "Pending" | "Approved" | "Rejected" | "Cancelled"; mine?: boolean; limit?: number }): Promise<ApprovalOut[]> {
  return api<ApprovalOut[]>("GET", withQuery(`/approvals`, query), undefined);
}

/** Accounts Payable queue — GET /api/v1/finance/ap/queue (who may call: holders of finance.ap.view). */
export function apQueue(query?: { status?: string | null }): Promise<PayableQueueItemOut[]> {
  return api<PayableQueueItemOut[]>("GET", withQuery(`/finance/ap/queue`, query), undefined);
}

/** Settle Payment (vendor / contractor / visiting consultant) — POST /api/v1/finance/ap/{ap_id}/settle (who may call: holders of finance.ap.settle). */
export function settleAp(ap_id: number, body: SettleApIn): Promise<PayableSettlementOut> {
  return api<PayableSettlementOut>("POST", `/finance/ap/${ap_id}/settle`, body, { idempotent: true });
}

/** Returns to suppliers, newest first — GET /api/v1/pharmacy-admin/supplier-returns (who may call: holders of pharmacy.supplier_return.record or finance.supplier_credit.confirm or finance.ap.view). */
export function listReturnsPharmacyAdminSupplier(query?: { status?: "Returned" | "Credited" | "Refused" | null; vendor_id?: number | null; limit?: number }): Promise<SupplierReturnOut[]> {
  return api<SupplierReturnOut[]>("GET", withQuery(`/pharmacy-admin/supplier-returns`, query), undefined);
}

/** One return to a supplier — GET /api/v1/pharmacy-admin/supplier-returns/{return_id} (who may call: holders of pharmacy.supplier_return.record or finance.supplier_credit.confirm or finance.ap.view). */
export function getReturn(return_id: number): Promise<SupplierReturnOut> {
  return api<SupplierReturnOut>("GET", `/pharmacy-admin/supplier-returns/${return_id}`, undefined);
}

/** The return note that goes with the goods (PDF) — GET /api/v1/pharmacy-admin/supplier-returns/{return_id}/pdf (who may call: holders of pharmacy.supplier_return.record or finance.supplier_credit.confirm). */
export function returnNote(return_id: number): Promise<unknown> {
  return api<unknown>("GET", `/pharmacy-admin/supplier-returns/${return_id}/pdf`, undefined);
}

/** Confirm the supplier's credit note for a return — POST /api/v1/finance/supplier-returns/{return_id}/credit (who may call: holders of finance.supplier_credit.confirm). */
export function confirmCredit(return_id: number, body: SupplierCreditIn): Promise<SupplierReturnOut> {
  return api<SupplierReturnOut>("POST", `/finance/supplier-returns/${return_id}/credit`, body);
}

/** Record that the supplier gives no credit for a return — POST /api/v1/finance/supplier-returns/{return_id}/refuse (who may call: holders of finance.supplier_credit.confirm). */
export function refuseCredit(return_id: number, body: SupplierRefusalIn): Promise<SupplierReturnOut> {
  return api<SupplierReturnOut>("POST", `/finance/supplier-returns/${return_id}/refuse`, body);
}
